import { QueryClient } from '@tanstack/react-query';
import { createRouter } from '@tanstack/react-router';
import { routeTree } from './routeTree.gen.js';

// TanStack Query owns the session truth (AD-014) — the queryClient goes
// into the router context so _private/route.tsx (beforeLoad) calls
// ensureQueryData(sessionQuery) without needing Zustand.
export const queryClient = new QueryClient();

// AD-030: routeTree generated by @tanstack/router-plugin (createFileRoute in
// each route file) — no manual addChildren composition here.
// Search params as they read (AD-257): text goes as is (`?q=123`, not `?q=%22123%22`) and only lists and objects go
// as JSON. Every scalar comes back as text, so a numeric field coerces it in its page schema (`z.coerce.number()`) and
// a search made of digits stays text. Text that starts like JSON is quoted, so it reads back the same.
const asJson = (value: unknown) => typeof value === 'object' || (typeof value === 'string' && /^[[{"]/.test(value));

function stringifySearch(search: Record<string, unknown>) {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(search)) {
    if (value !== undefined) params.set(key, asJson(value) ? JSON.stringify(value) : String(value));
  }
  const text = params.toString();
  return text ? `?${text}` : '';
}

function parseSearch(text: string) {
  const search: Record<string, unknown> = {};
  for (const [key, value] of new URLSearchParams(text)) {
    try {
      search[key] = asJson(value) ? JSON.parse(value) : value;
    } catch {
      search[key] = value;
    }
  }
  return search;
}

export const router = createRouter({ routeTree, context: { queryClient }, parseSearch, stringifySearch });

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router;
  }
}
